import numpy as np

def make_input(agent_rc, wall=True):
    X = np.zeros((1, 500))
    r, c = agent_rc
    X[0, (r * 10 + c) * 5 + 0] = 1.0
    if wall:
        for rr in range(10):
            for cc in range(10):
                if rr == 0 or rr == 9 or cc == 0 or cc == 9:
                    X[0, (rr * 10 + cc) * 5 + 3] = 1.0
    return X

