rows = []
labels = []
for pos in positions:
    for wall in [False, True]:
        rows.append(make_input(pos, wall=wall))
        labels.append((pos, wall))

X = np.vstack(rows)
out = forward(X)

if np.all(out >= 0) and np.allclose(out.sum(axis=1), 1.0):
    probs = out
else:
    probs = np.exp(out - out.max(axis=1, keepdims=True))
    probs = probs / probs.sum(axis=1, keepdims=True)

actions = ['noop', 'up', 'down', 'left', 'right']
for (pos, wall), p in zip(labels, probs):
