dirs = [(-1, 0, 'up', 1), (1, 0, 'down', 2), (0, -1, 'left', 3), (0, 1, 'right', 4)]

batch = []
for ag in positions:
    batch.append(obs(agent=ag, prev=ag))
    for dr, dc, nm, ta in dirs:
        batch.append(obs(agent=ag, prev=ag, reward=(ag[0] + dr, ag[1] + dc)))

P = run(batch)
toward = 0; tot = 0; i = 0
print('agent    base  |  rew_up rew_dn rew_lt rew_rt   (* = toward reward)')
for ag in positions:
    b = P[i]; i += 1
    row = []
    for dr, dc, nm, ta in dirs:
        p = P[i]; i += 1
        a = int(np.argmax(p)); tot += 1
        mark = '*' if a == ta else ' '
        row.append(actions[a] + mark)
        if a == ta:
            toward += 1
    print('%-8s %-5s |  ' % (str(ag), actions[int(np.argmax(b))]) +
          '  '.join('%-6s' % x for x in row))
print('\nReward-toward: %d/%d = %.0f%%' % (toward, tot, 100.0 * toward / tot))

import numpy as np

def idx(r, c, ch):
    return (r * 10 + c) * 5 + ch

def make_obs(agent, reward=None, prev=None):
    x = np.zeros(500, dtype=float)
    # wall border in channel 3
    for r in range(10):
        for c in range(10):
            if r in (0, 9) or c in (0, 9):
                x[idx(r, c, 3)] = 1.0
    ar, ac = agent
    x[idx(ar, ac, 0)] = 1.0
    if reward is not None:
        rr, rc = reward
        x[idx(rr, rc, 2)] = 1.0
    if prev is not None:
        pr, pc = prev
        x[idx(pr, pc, 4)] = 1.0
    return x

positions = [(5, 5), (3, 3)]
prev_options = [('none', None), ('up', (-1, 0)), ('down', (1, 0)),
                ('left', (0, -1)), ('right', (0, 1))]
reward_options = [('none', None), ('up', (-1, 0)), ('down', (1, 0)),
                  ('left', (0, -1)), ('right', (0, 1))]

X = []
meta = []
for ar, ac in positions:
    for pname, pdelta in prev_options:
        if pdelta is None:
            prev = None
        else:
            prev = (ar + pdelta[0], ac + pdelta[1])
            if not (1 <= prev[0] <= 8 and 1 <= prev[1] <= 8):
                continue
        for rname, rdelta in reward_options:
            if rdelta is None:
                reward = None
            else:
                reward = (ar + rdelta[0], ac + rdelta[1])
                if not (1 <= reward[0] <= 8 and 1 <= reward[1] <= 8):
                    continue
            X.append(make_obs((ar, ac), reward, prev))
            meta.append((ar, ac, pname, rname))

X = np.array(X)
logits = forward(X)
actions = np.argmax(logits, axis=1)
action_names = ['noop', 'up', 'down', 'left', 'right']

print("agent   prev    reward  -> action (prob)")
for i, (ar, ac, pname, rname) in enumerate(meta):
    p = np.exp(logits[i] - logits[i].max())
    p = p / p.sum()
    print(f"({ar},{ac}) {pname:5s}  {rname:5s}  -> {action_names[actions[i]]:4s} ({p[actions[i]]:.2f})")
